# ------------------------------------------------------------------
# Luau-compatibility preprocessor — strips type annotations and other
# Luau-only syntax Kryos cannot parse, BEFORE the engine sees the
# script.  Token-aware: strings, comments and long-brackets are
# never modified.
# ------------------------------------------------------------------
"""
Kryos preprocessor — fixes Luau syntax that Kryos' compiler can't parse,
so obfuscation succeeds instead of erroring with "Expected '(' got ':'".

Handled (token-aware; strings & comments are never touched):
  1. Type annotations in function definitions:
       function f(a: number, b: string): boolean  ->  function f(a, b)
       local function f<T>(x: T): T               ->  local function f(x)
       function t:foo(): number                   ->  function t:foo()
     Method/dotted definition sugar is desugared by this preprocessor too;
     the replacement Lua engine does not parse it itself.
  2. `for i: T = 1, 10 do`  ->  `for i = 1, 10 do`
     `for k: T, v: U in pairs(t) do`  ->  `for k, v in pairs(t) do`
  3. Double unary signs: `- -5`, `+ +5`, `- - x` -> collapsed by parity
     (`a = - -5`  ==  `a = 5`; `return - -x` == `return x`).
     Only in unary context, so `a - -b` (binary minus) is left alone.
  4. Parenless call arguments (function OR method calls):
       print "Players"        ->  print("Players")
       game:GetService "P"    ->  game:GetService("P")
       f {x = 1}              ->  f({x = 1})
       print "a" .. "b"       ->  print("a") .. "b"   (matches Luau: the
                                string arg binds only the string literal)
     Covers keywords/globals/locals/chains; a pure token wrapper, so string
     and comment contents are never inspected or modified.

Type-annotation scanning respects nesting: ( ) [ ] { } < > are counted, so
types like `{x: number}` or `(number) -> string` are skipped in one piece.
"""

import re

_PUNCT = ("...", "::", "//", "<<", ">>", "==", "~=", "<=", ">=", "..",
          "->", "|>", "(", ")", "[", "]", "{", "}", "<", ">", ",", ":",
          ";", "=", "+", "-", "*", "/", "%", "^", "#", "&", "|", "~", ".")
_KEYWORDS = {
    "and", "break", "do", "else", "elseif", "end", "false", "for",
    "function", "goto", "if", "in", "local", "nil", "not", "or",
    "repeat", "return", "then", "true", "until", "while", "continue",
}
_STMT_STARTERS = {"return", "local", "end", "if", "while", "for", "repeat",
                  "break", "goto", "function", "do", "else", "elseif",
                  "until", "then", "continue"}
_OPENS = ("(", "[", "{", "<")
_CLOSES = (")", "]", "}", ">")


def _tokenize(src):
    """Yield (kind, value, start, end). kind: id, num, str, op, ws, comment."""
    i, n = 0, len(src)
    while i < n:
        c = src[i]
        if c in " \t\r\n\f\v":
            j = i + 1
            while j < n and src[j] in " \t\r\n\f\v":
                j += 1
            yield ("ws", src[i:j], i, j)
            i = j
            continue
        if c == "-" and src.startswith("--", i):
            j = i + 2
            lb = _long_bracket(src, j)
            if lb is not None:
                start, eq = lb
                close = _find_long_close(src, start, eq)
                j = n if close is None else close
            else:
                while j < n and src[j] not in "\r\n":
                    j += 1
            yield ("comment", src[i:j], i, j)
            i = j
            continue
        if c == '"' or c == "'":
            j = i + 1
            while j < n:
                if src[j] == "\\":
                    j += 2
                    continue
                if src[j] == c:
                    j += 1
                    break
                j += 1
            yield ("str", src[i:j], i, j)
            i = j
            continue
        lb = _long_bracket(src, i)
        if lb is not None:
            start, eq = lb
            close = _find_long_close(src, start, eq)
            j = n if close is None else close
            yield ("str", src[i:j], i, j)
            i = j
            continue
        if c.isdigit() or (c == "." and i + 1 < n and src[i + 1].isdigit()):
            m = re.match(r"0[xX][0-9a-fA-F]+(\.[0-9a-fA-F]*)?([pP][+-]?\d+)?"
                         r"|\d+(\.\d*)?([eE][+-]?\d+)?", src[i:])
            j = i + m.end()
            yield ("num", src[i:j], i, j)
            i = j
            continue
        if c.isalpha() or c == "_":
            j = i + 1
            while j < n and (src[j].isalnum() or src[j] == "_"):
                j += 1
            yield ("id", src[i:j], i, j)
            i = j
            continue
        matched = None
        for p in _PUNCT:
            if src.startswith(p, i):
                matched = p
                break
        if matched is not None:
            yield ("op", matched, i, i + len(matched))
            i += len(matched)
            continue
        yield ("op", c, i, i + 1)
        i += 1


def _long_bracket(src, i):
    if not src.startswith("[", i):
        return None
    j = i + 1
    while j < len(src) and src[j] == "=":
        j += 1
    if j < len(src) and src[j] == "[":
        return (j + 1, j - i - 1)
    return None


def _find_long_close(src, start, eq):
    """End position (exclusive) of the closing ]] / ]=] marker, or None."""
    marker = "]" + "=" * eq + "]"
    pos = src.find(marker, start)
    return None if pos < 0 else pos + len(marker)


def _newline_after(src, pos):
    """Position of the first '\n' at/after pos, or len(src) if none."""
    i = src.find("\n", pos)
    return len(src) if i < 0 else i


def _strip_annotations(src):
    toks = list(_tokenize(src))
    n = len(toks)
    idx = [i for i, t in enumerate(toks) if t[0] not in ("ws", "comment")]
    drop = set()

    # ---- function definitions --------------------------------------------
    for p, ti in enumerate(idx):
        kind, val = toks[ti][0], toks[ti][1]
        if not (kind == "id" and val == "function"):
            continue
        q = p + 1
        # name path: id ( ( . | : ) id )*
        while q < len(idx):
            t2 = toks[idx[q]]
            if t2[0] == "id":
                # generics right after this name: f<T, U>
                if q + 1 < len(idx) and toks[idx[q + 1]][0] == "op" \
                        and toks[idx[q + 1]][1] == "<":
                    end = _match(toks, idx, q + 1)
                    if end is not None:
                        for z in range(q + 1, end + 1):
                            drop.add(idx[z])
                        q = end + 1
                        continue
                if q + 1 < len(idx) and toks[idx[q + 1]][0] == "op" \
                        and toks[idx[q + 1]][1] in (".", ":"):
                    q += 2
                    continue
                q += 1
                break
            break
        if q >= len(idx):
            continue
        if toks[idx[q]][0] == "op" and toks[idx[q]][1] == "(":
            end = _match(toks, idx, q)
            if end is None:
                continue
            _strip_param_types(toks, idx, q, end, drop)
            r = end + 1
            if r < len(idx) and toks[idx[r]][0] == "op" \
                    and toks[idx[r]][1] == ":":
                last = _type_tail(toks, idx, r, src)
                for z in range(r, last + 1):
                    drop.add(idx[z])

    # ---- local x: T = ... --------------------------------------------------
    for p, ti in enumerate(idx):
        if not (toks[ti][0] == "id" and toks[ti][1] == "local"):
            continue
        q = p + 1
        if q >= len(idx):
            continue
        # `local function` — handled elsewhere; skip
        if toks[idx[q]][0] == "id" and toks[idx[q]][1] in _STMT_STARTERS:
            continue
        # walk names: id ( , id )*  — after a name, strip `: T` up to , / =
        k = q
        expect_name = True
        while k < len(idx):
            t = toks[idx[k]]
            if expect_name:
                if t[0] == "id":
                    expect_name = False
                    k += 1
                    continue
                break
            if t[0] == "op":
                if t[1] == ",":
                    expect_name = True
                    k += 1
                    continue
                if t[1] == ":":
                    # strip type tokens until , = or newline (depth 0)
                    d = 0
                    nl = _newline_after(src, toks[idx[k]][3])
                    kk = k + 1
                    while kk < len(idx):
                        tt = toks[idx[kk]]
                        if toks[idx[kk]][2] > nl:
                            break
                        if tt[0] == "op" and tt[1] in _OPENS:
                            d += 1
                        elif tt[0] == "op" and tt[1] in _CLOSES:
                            d = max(0, d - 1)
                        elif tt[0] == "op" and tt[1] in (",", "=") and d == 0:
                            break
                        kk += 1
                    for z in range(k, kk):
                        drop.add(idx[z])
                    k = kk
                    continue
                break
            break

    # ---- for i: T = ... | for k: T, v: U in ... --------------------------
    for p, ti in enumerate(idx):
        if not (toks[ti][0] == "id" and toks[ti][1] == "for"):
            continue
        q = p + 1
        if q >= len(idx):
            continue
        # walk the variable list: name (: type)? (, name (: type)?)* ,
        # then the terminator `=` (numeric for) or `in` (generic for).
        # Only the `: type` parts are dropped; names and terminator survive.
        k = q
        while k < len(idx):
            t = toks[idx[k]]
            if t[0] != "id":
                break
            k += 1
            if k < len(idx) and toks[idx[k]][0] == "op" \
                    and toks[idx[k]][1] == ":":
                start = k
                d = 0
                k += 1
                while k < len(idx):
                    tt = toks[idx[k]]
                    if tt[0] == "op":
                        if tt[1] in _OPENS:
                            d += 1
                        elif tt[1] in _CLOSES:
                            d = max(0, d - 1)
                        elif d == 0 and tt[1] in (",", "="):
                            break
                    elif d == 0 and tt[0] == "id" and tt[1] == "in":
                        break
                    k += 1
                for z in range(start, k):
                    drop.add(idx[z])
            if k < len(idx) and toks[idx[k]][0] == "op" \
                    and toks[idx[k]][1] == ",":
                k += 1
                continue
            break

    if not drop:
        return src
    # tidy: drop whitespace (without newlines) that sat next to a dropped token
    drop = _tidy_ws(toks, drop)
    return "".join(src[toks[i][2]:toks[i][3]] for i in range(n) if i not in drop)


def _tidy_ws(toks, drop):
    """Extend `drop` with ws tokens adjacent to dropped tokens (no newlines).
    Afterwards, never allow the removal to glue two word-like tokens
    together (``v`` + ``in`` must not become the identifier ``vin``)."""
    changed = True
    while changed:
        changed = False
        for i, t in enumerate(toks):
            if i in drop or t[0] != "ws" or "\n" in t[1]:
                continue
            # significant neighbors
            left = next((j for j in range(i - 1, -1, -1)
                         if toks[j][0] not in ("ws", "comment")), None)
            right = next((j for j in range(i + 1, len(toks))
                          if toks[j][0] not in ("ws", "comment")), None)
            if (left is not None and left in drop) or \
               (right is not None and right in drop):
                drop.add(i)
                changed = True
    # keep one separator inside any gap that would otherwise join word tokens
    sig = [i for i, t in enumerate(toks) if t[0] not in ("ws", "comment")]
    for a, b in zip(sig, sig[1:]):
        la, lb = toks[a], toks[b]
        if la[0] not in ("id", "num") or lb[0] not in ("id", "num"):
            continue
        if any(toks[i][0] == "comment" for i in range(a + 1, b)):
            continue  # a comment still separates the two tokens
        for i in range(b - 1, a, -1):
            if toks[i][0] == "ws" and i in drop:
                drop.discard(i)  # keep the separator closest to the right
                break
    return drop


def _match(toks, idx, open_p):
    """Structural index of the closer for the opener at idx[open_p]."""
    depth = 0
    for k in range(open_p, len(idx)):
        t = toks[idx[k]]
        if t[0] == "op":
            if t[1] in _OPENS:
                depth += 1
            elif t[1] in _CLOSES:
                depth -= 1
                if depth == 0:
                    return k
    return None


def _type_tail(toks, idx, colon_p, src):
    """From a ':' token (structural index), consume a type expression.
    Returns the structural index of the last type token (inclusive)."""
    depth = 0
    k = colon_p
    last = colon_p
    nl = _newline_after(src, toks[idx[colon_p]][3])
    while k < len(idx):
        if toks[idx[k]][2] > nl:
            break
        t = toks[idx[k]]
        if t[0] == "op":
            if t[1] in _OPENS:
                depth += 1
                last = k
            elif t[1] in _CLOSES:
                if depth == 0:
                    break
                depth -= 1
                last = k
            elif depth == 0 and t[1] in (",", ";", "="):
                break
            else:
                last = k
        elif t[0] == "id":
            if depth == 0:
                if t[1] in _STMT_STARTERS:
                    break
                # a bare identifier can only continue a type after one of these
                prev_tok = toks[idx[k - 1]][1] if k > colon_p else None
                if last > colon_p and prev_tok not in (
                        "|", "&", ".", "<", "->", "(", ":", ","):
                    break
            last = k
        else:
            last = k
        k += 1
    return last


def _strip_param_types(toks, idx, lparen_p, rparen_p, drop):
    """Within a function param list, remove ': type' after each parameter."""
    depth = 0
    k = lparen_p + 1
    while k < rparen_p:
        t = toks[idx[k]]
        if t[0] == "op":
            if t[1] in _OPENS:
                depth += 1
            elif t[1] in _CLOSES:
                depth = max(0, depth - 1)
            elif t[1] == "?" and depth == 0:
                # Luau optional param marker: `a?` before ',' or ')'
                prev_tok = toks[idx[k - 1]] if k > lparen_p else None
                nxt_tok = toks[idx[k + 1]] if k + 1 < rparen_p else None
                if prev_tok is not None and prev_tok[0] == "id" and (
                        nxt_tok is None or
                        (nxt_tok[0] == "op" and nxt_tok[1] in (",", ")", ":"))):
                    drop.add(idx[k])
            elif t[1] == ":" and depth == 0:
                prev_tok = toks[idx[k - 1]] if k > lparen_p else None
                # optional marker: `a?: T` — the '?' belongs to the annotation
                start_k = k
                if prev_tok is not None and prev_tok[0] == "op" \
                        and prev_tok[1] == "?" and k - 2 > lparen_p:
                    start_k = k - 1
                    prev_tok = toks[idx[k - 2]]
                if prev_tok is not None and (
                        prev_tok[0] == "id" or prev_tok[1] in ("]", ")", ">")):
                    last = k
                    d2 = 0
                    kk = k + 1
                    while kk < rparen_p:
                        tt = toks[idx[kk]]
                        if tt[0] == "op" and tt[1] in _OPENS:
                            d2 += 1
                        elif tt[0] == "op" and tt[1] in _CLOSES:
                            if d2 == 0 and tt[1] in (",", ")"):
                                break
                            d2 = max(0, d2 - 1)
                        elif tt[0] == "op" and tt[1] == "," and d2 == 0:
                            break
                        last = kk
                        kk += 1
                    for z in range(start_k, last + 1):
                        drop.add(idx[z])
                    k = last + 1
                    continue
        k += 1


def _collapse_double_unary(src):
    toks = list(_tokenize(src))
    idx = [i for i, t in enumerate(toks) if t[0] not in ("ws", "comment")]
    drop = set()
    for p, ti in enumerate(idx):
        t = toks[ti]
        if not (t[0] == "op" and t[1] in ("+", "-")):
            continue
        q = p
        signs = []
        while q < len(idx) and toks[idx[q]][0] == "op" \
                and toks[idx[q]][1] in ("+", "-"):
            signs.append(toks[idx[q]][1])
            q += 1
        if len(signs) < 2:
            continue
        prev = toks[idx[p - 1]][1] if p > 0 else None
        unary_ctx = prev is None or prev in (
            "=", "(", "[", "{", ",", ";", ":", "~",
            "+", "-", "*", "/", "%", "^", "..", "<", ">", "&", "|",
            "and", "or", "not", "return", "then", "do", "else", "in",
            "until", "repeat") or prev in _STMT_STARTERS
        if not unary_ctx:
            continue
        for z in range(p, q):
            drop.add(idx[z])
        if signs.count("-") % 2 == 1:
            drop.discard(idx[p])
    if not drop:
        return src
    drop = _tidy_ws(toks, drop)
    return "".join(src[toks[i][2]:toks[i][3]] for i in range(len(toks))
                   if i not in drop)


def _parenthesize_parenless(src):
    """Wrap bare string / table-constructor call arguments in parentheses.

    ``print "x"``, ``game:GetService "P"``, ``f {a = 1}`` and their chained
    variants (``a.b "x"``, ``a[1] "x"``, ``f() "x"``) are valid Luau sugar
    that Kryos' expression parser only accepts in a few local-name positions.
    This pass rewrites every occurrence into an ordinary call — the result is
    identical Luau/Lua with the sugar removed.  Token-level only: string and
    comment contents are opaque, so ``print "a .. b"`` is untouched.
    """
    toks = list(_tokenize(src))
    idx = [i for i, t in enumerate(toks) if t[0] not in ("ws", "comment")]
    edits = []

    def is_endpoint(p):
        """Can significant token p end a callable prefix expression?"""
        t = toks[idx[p]]
        prev = toks[idx[p - 1]] if p > 0 else None
        if t[0] == "id":
            if t[1] in _KEYWORDS:
                return False
            if prev is None:
                return True
            if prev[0] == "op":
                return True
            # keyword id (return / in / and / ... ) starts a fresh expression
            if prev[0] == "id" and prev[1] in _KEYWORDS:
                return True
            return False
        if t[0] == "op" and t[1] in (")", "]", "}"):
            return True
        return False

    for p in range(len(idx) - 1):
        if not is_endpoint(p):
            continue
        nxt = toks[idx[p + 1]]
        end_pos = None
        if nxt[0] == "str":
            # Luau binds the string literal itself: `f "a" .. "b"` parses as
            # `f("a") .. "b"` — so only the string gets parenthesized.
            end_pos = nxt[3]
        elif nxt[0] == "op" and nxt[1] == "{":
            # Table constructor. Brace depth is enough: braces inside strings,
            # comments and long brackets are single opaque tokens.
            depth = 0
            for q in range(p + 1, len(idx)):
                token = toks[idx[q]]
                if token[0] != "op":
                    continue
                if token[1] == "{":
                    depth += 1
                elif token[1] == "}":
                    depth -= 1
                    if depth == 0:
                        end_pos = token[3]
                        break
        if end_pos is not None:
            # Put `(` where the call stays unambiguous: if a newline sits
            # between the callee and the argument, `(` must stay on the
            # callee's line (Luau errors on "f <newline> (arg)" in expression
            # context as an ambiguous call).
            between = src[toks[idx[p]][3]:nxt[2]]
            open_pos = toks[idx[p]][3] if "\n" in between else nxt[2]
            edits.append((open_pos, "("))
            edits.append((end_pos, ")"))

    if not edits:
        return src

    # Apply right-to-left so every position remains an offset into `src`.
    # At an equal position a closing parenthesis belongs before an opening one.
    for pos, text in sorted(edits, key=lambda item: (item[0], item[1] == "("),
                            reverse=True):
        src = src[:pos] + text + src[pos:]
    return src


def _desugar_function_definitions(src):
    """Lower named table functions without touching comments or literals.

    function a.b(x)    -> a.b = function(x)
    function a:b(x)    -> a.b = function(self,x)

    The new Lua engine accepts assignments of anonymous functions, but not
    dotted/colon function definitions. Plain and local functions stay intact.
    Run after annotation stripping so typed method signatures work too.
    """
    toks = [t for t in _tokenize(src) if t[0] not in ("ws", "comment")]
    edits = []
    for i, tok in enumerate(toks):
        if tok[:2] != ("id", "function"):
            continue
        if i and toks[i - 1][:2] == ("id", "local"):
            continue
        j = i + 1
        if j >= len(toks) or toks[j][0] != "id":
            continue
        j += 1
        separators = []
        while (j + 1 < len(toks) and toks[j][0] == "op"
               and toks[j][1] in (".", ":") and toks[j + 1][0] == "id"):
            separators.append(toks[j])
            j += 2
        if not separators or j >= len(toks) or toks[j][:2] != ("op", "("):
            continue
        # A colon is only valid before the final name in the path.
        if any(t[1] == ":" for t in separators[:-1]):
            continue
        edits.append((tok[2], tok[3], ""))
        edits.append((toks[j][2], toks[j][2], "= function"))
        if separators[-1][1] == ":":
            colon = separators[-1]
            edits.append((colon[2], colon[3], "."))
            no_params = j + 1 < len(toks) and toks[j + 1][:2] == ("op", ")")
            edits.append((toks[j][3], toks[j][3], "self" if no_params else "self,"))
    for start, end, replacement in sorted(edits, reverse=True):
        src = src[:start] + replacement + src[end:]
    return src


def preprocess(source):
    """Apply all Kryos-compatibility fixes. Returns the adjusted source."""
    if not source:
        return source
    src = _strip_annotations(source)
    src = _desugar_function_definitions(src)
    src = _collapse_double_unary(src)
    src = _parenthesize_parenless(src)
    return src




_engine_source = None


def _prepare_engine_source(source: str) -> str:
    """Pin the actual Lua setting to 3, ignoring comments and string literals."""
    if not source.strip() or BANNER not in source:
        raise RuntimeError(
            "The bundle must contain the Kryos v16.2 obfuscator source, "
            "not an obfuscated output script."
        )
    tokens = [t for t in _tokenize(source) if t[0] not in ("ws", "comment")]
    settings = []
    for i in range(len(tokens) - 3):
        if (tokens[i][:2] == ("id", "local")
                and tokens[i + 1][:2] == ("id", "optimization_level")
                and tokens[i + 2][:2] == ("op", "=")):
            value = tokens[i + 3]
            if value[0] != "num" or value[1] not in ("1", "2", "3"):
                raise RuntimeError("The engine's optimization_level must be a literal 1, 2, or 3.")
            # Reject computed settings instead of accidentally keeping part of
            # an expression after replacing the literal (e.g. '1 + 1').
            if i + 4 < len(tokens) and tokens[i + 4][1] in (
                "+", "-", "*", "/", "//", "%", "^", "..", "and", "or",
                "&", "|", "~", "<<", ">>", "==", "~=", "<", ">", "<=", ">=",
            ):
                raise RuntimeError("Use a single literal for the engine's optimization_level.")
            settings.append(value)
    if len(settings) != 1:
        raise RuntimeError(
            "Expected exactly one optimization_level setting in the bundled source. "
            "Upload the complete updated engine.py and redeploy."
        )
    value = settings[0]
    return source[:value[2]] + str(OPTIMIZATION_LEVEL) + source[value[3]:]


def _load_engine_source() -> str:
    global _engine_source
    if _engine_source is not None:
        return _engine_source
    try:
        data = base64.b64decode(_KRYOS_LUA_B64, validate=True)
        source = zlib.decompress(data).decode("utf-8")
        prepared = _prepare_engine_source(source)
    except Exception:
        raise RuntimeError(
            "Bundled Kryos source is invalid or incomplete. Upload the full "
            "updated engine.py and redeploy; no key or Secret File is needed."
        ) from None
    checksum = hashlib.sha256(prepared.encode("utf-8")).hexdigest()
    if checksum != _KRYOS_SOURCE_SHA256:
        raise RuntimeError(
            "Bundled Kryos source checksum does not match. Upload the complete "
            "updated engine.py and redeploy."
        )
    _logger.info("Kryos bundled source loaded: optimization_level=3 source_sha256=%s", checksum)
    _engine_source = prepared
    return _engine_source


# ------------------------------------------------------------------
def _write_lua_bin(directory: str) -> str:
    path = os.path.join(directory, "lua54")
    data = zlib.decompress(base64.b64decode(_LUA_BIN))
    with open(path, "wb") as f:
        f.write(data)
    os.chmod(path, stat.S_IRUSR | stat.S_IWUSR | stat.S_IXUSR
             | stat.S_IRGRP | stat.S_IXGRP | stat.S_IROTH | stat.S_IXOTH)
    return path


def _resolve_lua_bin(tmpdir: str) -> str:
    forced = os.environ.get("KRS_LUA_BIN", "").strip()
    if forced:
        if os.path.isfile(forced) and os.access(forced, os.X_OK):
            return forced
        raise RuntimeError(f"KRS_LUA_BIN is set but not executable: {forced}")
    # Bundled static Lua 5.4.8 — always present, always works.
    return _write_lua_bin(tmpdir)



def _inline_function_bundle(main_output: str, bundle: str) -> str:
    """Prefix a single output file with a one-time native bundle bootstrap."""
    if not isinstance(bundle, str) or not bundle.strip().startswith("return {"):
        raise ValueError("invalid function bundle")
    encoded = base64.b64encode(bundle.encode("utf-8")).decode("ascii")
    # The bundle source is transported as base64 rather than visible ordinary
    # Lua. It is decoded and compiled once by the host runtime before the
    # custom VM starts. This preserves the one-file Discord UX while keeping
    # the extracted function bodies out of the VM prototype payload.
    bootstrap = f'''local __krs_bundle_b64={json.dumps(encoded)}
local __krs_bundle_alpha="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local __krs_bundle_rev={{}}
for __krs_i=1,#__krs_bundle_alpha do
    __krs_bundle_rev[#__krs_bundle_rev+1]=__krs_bundle_alpha:sub(__krs_i,__krs_i)
end
local __krs_bundle_decode=function(__krs_s)
    local __krs_out={{}}
    local __krs_acc=0
    local __krs_bits=0
    for __krs_i=1,#__krs_s do
        local __krs_c=__krs_s:sub(__krs_i,__krs_i)
        local __krs_v=__krs_bundle_alpha:find(__krs_c,1,true)
        if __krs_v then
            __krs_acc=__krs_acc*64+__krs_v-1
            __krs_bits=__krs_bits+6
            while __krs_bits>=8 do
                __krs_bits=__krs_bits-8
                __krs_out[#__krs_out+1]=string.char(math.floor(__krs_acc/2^__krs_bits)%256)
                __krs_acc=__krs_acc%2^__krs_bits
            end
        end
    end
    return table.concat(__krs_out)
end
local __krs_bundle_env=(getfenv and getfenv()) or _ENV
local __krs_bundle_source=__krs_bundle_decode(__krs_bundle_b64)
local __krs_bundle_chunk
if loadstring and setfenv then
    __krs_bundle_chunk=assert(loadstring(__krs_bundle_source))
    -- A custom VM environment is not necessarily the process-global
    -- environment. Bind the ordinary bundle chunk to the exact same
    -- environment before it is executed, otherwise a native function can
    -- see nil for a VM-created global.
    setfenv(__krs_bundle_chunk,__krs_bundle_env)
elseif load then
    -- Lua-style `load` accepts an explicit environment. Prefer it when
    -- setfenv is absent, including executors that expose both loadstring and
    -- load but only provide the former as a compatibility alias.
    local __krs_load_ok,__krs_load_result=pcall(load,__krs_bundle_source,nil,"t",__krs_bundle_env)
    if __krs_load_ok and type(__krs_load_result)=="function" then
        __krs_bundle_chunk=__krs_load_result
    else
        __krs_bundle_chunk=assert(loadstring(__krs_bundle_source))
    end
else
    __krs_bundle_chunk=assert(loadstring(__krs_bundle_source))
end
local __krs_bundle=__krs_bundle_chunk()
__krs_bundle_env["__KRS_FUNCTION_BUNDLE"]=__krs_bundle
'''
    return bootstrap + main_output

def _obfuscate_impl(source: str, *, with_bundle: bool):
    from obfuscator import ObfuscationError, EngineNotConfigured  # avoid cycles

    if not isinstance(source, str) or not source.strip():
        raise ObfuscationError("Empty script — nothing to obfuscate.")

    timeout = int(os.environ.get("OBF_ENGINE_TIMEOUT", "180") or 180)
    seed = str(int.from_bytes(os.urandom(6), "big") % 2 ** 31)
    source = preprocess(source)

    try:
        engine_src = _load_engine_source()
    except RuntimeError as exc:
        raise EngineNotConfigured(str(exc)) from exc

    try:
        with tempfile.TemporaryDirectory(prefix="krs_") as tmp:
            engine_path = os.path.join(tmp, "engine.lua")
            with open(engine_path, "w", encoding="utf-8") as f:
                f.write(engine_src)
            src_path = os.path.join(tmp, "input.lua")
            with open(src_path, "w", encoding="utf-8") as f:
                f.write(source)
            bundle_path = os.path.join(tmp, "bundle.lua")
            lua_bin = _resolve_lua_bin(tmp)
            command = [lua_bin, engine_path, src_path, seed]
            if with_bundle:
                command.append(bundle_path)
            try:
                proc = subprocess.run(
                    command,
                    capture_output=True,
                    timeout=timeout,
                )
            except subprocess.TimeoutExpired:
                raise ObfuscationError(
                    f"Kryos took longer than {timeout}s and was killed. "
                    "Try a smaller script or raise OBF_ENGINE_TIMEOUT."
                )

            if proc.returncode != 0:
                err = proc.stderr.decode("utf-8", "replace").strip()
                # Don't leak server paths in user-facing errors.
                err = err.replace(tmp, "…").replace(engine_path, "engine.lua")
                raise ObfuscationError(
                    "Kryos errored: " + (err[-2000:] or "no error output")
                )

            result = proc.stdout.decode("utf-8", "replace")
            if BANNER not in result:
                raise ObfuscationError(
                    "Kryos output is missing its banner — the engine did not "
                    "produce a valid obfuscated script."
                )
            if not with_bundle:
                return result

            try:
                with open(bundle_path, "r", encoding="utf-8") as f:
                    bundle = f.read()
            except OSError as exc:
                raise ObfuscationError(
                    f"Kryos did not produce the function bundle: {exc}"
                ) from exc
            if not bundle.strip().startswith("return {"):
                raise ObfuscationError(
                    "Kryos produced an invalid function bundle."
                )
            return _inline_function_bundle(result, bundle), bundle
    except ObfuscationError:
        raise
    except Exception as exc:
        raise ObfuscationError(str(exc)) from exc


def obfuscate(source: str) -> str:
    """Legacy single-output API.

    The bundle-aware bot path uses ``obfuscate_with_bundle``. This method is
    retained for callers that only need generation/diagnostics, but its output
    requires the host bundle preload contract when extracted functions exist.
    """
    return _obfuscate_impl(source, with_bundle=False)


def obfuscate_with_bundle(source: str):
    """Return ``(main_output, function_bundle)`` from one compiler run."""
    return _obfuscate_impl(source, with_bundle=True)
